def find_zero(xs: list):
    """
    Evaluates the root of the polynomial xs for which largest coefficient is non-zero and
    returns only one zero point. Assumes xs has even number of coefficients.
    """
    if len(xs) % 2 != 0:
        raise ValueError("xs must have an even number of coefficients")

    n = len(xs)
    half = n // 2

    def f(x):
        return poly(xs[:half+1], x) - poly(xs[half:], x) * x

    low = 0
    high = 1
    result = 0.5

    while True:
        prev_result = result
        if f(result) == 0:
            return result
        if f(result) * f(low) < 0:
            high = result
        else:
            low = result
        result = (low + high) / 2
        if abs(result - prev_result) < 1e-10:
            return round(result, 2)
```

