    for row_idx, row in enumerate(lst):
        for col_idx, element in enumerate(row):
            if element == x:
                result.append((row_idx, col_idx))

    result.sort()  # sort by row ascending
    for row in lst:
        row_coords = [(r, c) for r, c in result if r == row_idx]
