def encode(message):
    vowels = 'aeiouAEIOU'
    encoded_message = []
    for char in message:
        if char in vowels:
            new_char = chr(ord(char) + 2)
            if char.islower():
                if new_char > 'u':
                    new_char = chr(ord('a') + (ord(new_char) - ord('u') - 1))
            else:
                if new_char > 'U':
                    new_char = chr(ord('A') + (ord(new_char) - ord('U') - 1))
            encoded_message.append(new_char)
        else:
            encoded_message.append(char.swapcase())
    return ''.join(encoded_message)
