def check_dict_case(dict):
    if not dict:
        return False
    case_types = []
    for key in dict:
        if not isinstance(key, str):
            return False
        if key.islower():
            case_types.append('lower')
        elif key.isupper():
            case_types.append('upper')
        else:
            return False
    return all(case == case_types[0] for case in case_types)
