def minPath(grid, k):
    n = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Priority queue: (path, last_position)
    heap = []
    visited = {}

    for i in range(n):
        for j in range(n):
            initial_path = [grid[i][j]]
            heapq.heappush(heap, (initial_path, (i, j)))
            visited[(i, j)] = initial_path.copy()

    while heap:
        path, (i, j) = heapq.heappop(heap)

        if len(path) == k:
            return path

        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n:
                new_path = path + [grid[ni][nj]]
                key = (ni, nj)
                if key not in visited or new_path < visited[key]:
                    visited[key] = new_path.copy()
                    heapq.heappush(heap, (new_path, key))

    return []
