def tri(n):
    """Return the first n + 1 numbers of the Tribonacci sequence."""
    if n == 0:
        return [1]

    sequence = [1] * (n + 1)
    sequence[0] = 1
    if n >= 1:
        sequence[1] = 3

    for i in range(2, n + 1):
        if i % 2 == 0:
            sequence[i] = 1 + i // 2
        else:
            sequence[i] = sequence[i - 1] + sequence[i - 2] + sequence[i + 1]
            # Handle potential out-of-bounds for i+1 when n < i+1
            if i + 1 <= n:
                pass
            else:
                sequence[i] = sequence[i - 1] + sequence[i - 2] + (1 + (i + 1) // 2)

    return sequence[:n + 1]
```

