def special_factorial(n):
    """The Brazilian factorial is defined as:
    brazilian_factorial(n) = n! * (n-1)! * (n-2)! * ... * 1!
    where n > 0

    For example:
    >>> special_factorial(4)
    288
    """
    if n <= 0:
        return 0

    def factorial(k):
        if k == 0 or k == 1:
            return 1
        return k * factorial(k - 1)

    result = 1
    for i in range(n, 0, -1):
        result *= factorial(i)
    return result
