def order_by_points(nums):
    def sum_digits(n):
        return sum(int(d) for d in str(abs(n)) if d.isdigit())

    indexed_nums = [(i, num) for i, num in enumerate(nums)]
    indexed_nums.sort(key=lambda x: (sum_digits(x[1]), x[0]))
    return [num for i, num in indexed_nums]
```

