def get_max_triples(n):
    count0 = 0
    count1 = 0
    count2 = 0
    for i in range(1, n + 1):
        num = i * i - i + 1
        mod = num % 3
        if mod == 0:
            count0 += 1
        elif mod == 1:
            count1 += 1
        else:
            count2 += 1

    return count0 * (count0 - 1) // 2 * count0 + count1 * (count1 - 1) // 2 * count1 + count2 * (count2 - 1) // 2 * count2 + count0 * count1 * count2
```

